cat > src/lib/email.ts <<'EOF'
import { postmark } from "@/lib/postmark";

const APP_URL = process.env.APP_URL ?? "http://localhost:3000";

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

async function send(to: string, subject: string, html: string, text: string) {
  if (!process.env.POSTMARK_SERVER_TOKEN || !process.env.POSTMARK_FROM_EMAIL) {
    console.warn(`[email] Postmark not configured, skipping "${subject}" to ${to}`);
    return;
  }
  // A failed email must never break the request that triggered it.
  try {
    await postmark.sendEmail({
      From: process.env.POSTMARK_FROM_EMAIL,
      To: to,
      Subject: subject,
      HtmlBody: html,
      TextBody: text,
      MessageStream: "outbound",
    });
  } catch (err) {
    console.error(`[email] failed to send "${subject}" to ${to}`, err);
  }
}

export async function sendWelcomeEmail(user: { email: string; name: string }) {
  await send(
    user.email,
    "Welcome to Notely",
    `<p>Hi ${escapeHtml(user.name)},</p><p>Welcome to Notely! Your account is ready.</p><p><a href="${APP_URL}/dashboard">Open your dashboard</a></p>`,
    `Hi ${user.name},\n\nWelcome to Notely! Your account is ready.\n\nOpen your dashboard: ${APP_URL}/dashboard`,
  );
}

export async function sendPasswordResetEmail(
  user: { email: string; name: string },
  token: string,
) {
  const url = `${APP_URL}/reset-password?token=${encodeURIComponent(token)}`;
  await send(
    user.email,
    "Reset your Notely password",
    `<p>Hi ${escapeHtml(user.name)},</p><p>We received a request to reset your password. This link expires in 1 hour:</p><p><a href="${url}">Reset password</a></p><p>If you didn't ask for this, you can ignore this email.</p>`,
    `Hi ${user.name},\n\nWe received a request to reset your password. This link expires in 1 hour:\n${url}\n\nIf you didn't ask for this, you can ignore this email.`,
  );
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// Only SHA-256 hashes of tokens are kept, so a leaked store can't be used to reset passwords.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Always resolves the same way whether or not the email is registered,
// so callers can't use it to discover which emails have accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const normalized = email.trim().toLowerCase();
  const user = users.find((u) => u.email === normalized);
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  await sendPasswordResetEmail(user, token);
}

// Validates and consumes a reset token; returns the user it belongs to.
// Setting the new password is left to the auth layer, which doesn't exist yet.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
EOF
